const output = [];

for (const item of $input.all()) {
  const data = item.json;

  let urls = data.urls || [];
  let domains = data.domains || [];

  // Prefer the actual Telegram message text. The stored message may be the raw
  // serialized Telegram JSON, so parse it and use its .text field when present.
  let text = data.message;
  if (typeof text === "string") {
    try {
      const parsed = JSON.parse(text);
      if (parsed && typeof parsed === "object" && typeof parsed.text === "string") {
        text = parsed.text;
      }
    } catch {
      // Not JSON: message is already plain text, keep as-is.
    }
  }

  // If URLs are not already extracted, get them from the clean message text.
  if (!urls.length && text) {
    urls = String(text).match(/https?:\/\/[^\s"\\]+/g) || [];
  }

  if (typeof urls === "string") {
    try {
      urls = JSON.parse(urls);
    } catch {
      urls = [];
    }
  }

  if (typeof domains === "string") {
    try {
      domains = JSON.parse(domains);
    } catch {
      domains = [];
    }
  }

  for (const url of urls) {
    output.push({
      json: {
        scan_id: data.id,
        indicator_type: "URL",
        value: url,
        vt_id: Buffer.from(url)
          .toString("base64")
          .replace(/=/g, "")
          .replace(/\+/g, "-")
          .replace(/\//g, "_")
      }
    });
  }

  for (const domain of domains) {
    output.push({
      json: {
        scan_id: data.id,
        indicator_type: "DOMAIN",
        value: domain
      }
    });
  }
}

return output;

