const vt = $input.first().json;

const original = $('If1').first().json;

return [{
  json: {
    scan_id: original.scan_id,
    indicator_type: original.indicator_type,
    value: original.value,
    vt_data: vt
  }
}];

const items = $input.all();

return items.map(item => {
  const d = item.json;

  const vt = d.vt_data?.data;
  const status = vt?.attributes?.status;

  // VirusTotal has not finished scanning yet
  if (status !== "completed") {
    return {
      json: {
        ...d,
        vt_status: status || "unknown",
        malicious: 0,
        suspicious: 0,
        harmless: 0,
        undetected: 0,
        risk_score: null,
        verdict: "ANALYZING"
      }
    };
  }

  const stats = vt.attributes.stats || {};

  const malicious = Number(stats.malicious || 0);
  const suspicious = Number(stats.suspicious || 0);
  const harmless = Number(stats.harmless || 0);
  const undetected = Number(stats.undetected || 0);

  const risk_score = Math.min(
    100,
    malicious * 30 + suspicious * 15
  );

  let verdict;

  if (risk_score >= 70) {
    verdict = "SCAM";
  } else if (risk_score >= 40) {
    verdict = "SUSPICIOUS";
  } else {
    verdict = "SAFE";
  }

  return {
    json: {
      ...d,
      malicious,
      suspicious,
      harmless,
      undetected,
      risk_score,
      verdict,
      vt_status: "completed"
    }
  };
});

const d = $('Update a row').first().json;

const r = $('Risk Engine').first().json;

if (d.verdict === "ANALYZING") {
  return [{
    json: {
      ...d,
      response: `🔄 ANALYZING

🔗 URL:
${Array.isArray(d.urls) ? d.urls.join("\n") : d.value || "Unknown"}

🛡️ VirusTotal is still processing this URL.

Please try again in a few seconds.

⚠️ Do not open or interact with this link.`
    }
  }];
}

const urls = Array.isArray(d.urls)
  ? d.urls
  : (r.value ? [r.value] : JSON.parse(d.urls || "[]"));

const response = `🚨 ${d.verdict}

🔗 URL:
${urls.join("\n")}

⚠️ Risk Score: ${d.risk_score}/100

🎯 Type: ${d.scam_type || "Unknown"}

🛡️ VirusTotal:

• Malicious: ${r.malicious}
• Suspicious: ${r.suspicious}
• Harmless: ${r.harmless}
• Undetected: ${r.undetected}

📝 Reason:
${d.reasons || "Analysis completed."}

⚠️ Do not open or interact with this link.`;

return [{
  json: {
    ...d,
    response
  }
}];

