  };

  const lines = [];
  const H = (t) => lines.push({ text: sanitize(t), bold: true, size: 13, gapBefore: 8 });
  const KV = (k, v) => lines.push({ text: sanitize(k + ": " + (v === null || v === undefined || v === "" ? "Not available" : v)), bold: false, size: 10 });
  const P = (t) => lines.push({ text: sanitize(t), bold: false, size: 10 });
  const BL = () => lines.push({ text: "", bold: false, size: 10 });
  const val = (v) => (v === null || v === undefined || v === "") ? null : v;

  const pdfIncidentId = r.incident_id != null ? r.incident_id : "N/A";
  const pdfThreatType = r.threat_type != null ? r.threat_type : "Unknown";

  lines.push({ text: sanitize("TruthLensAI Incident Report"), bold: true, size: 18 });
  lines.push({ text: sanitize("Incident ID: " + pdfIncidentId + "   |   Threat Type: " + pdfThreatType), bold: false, size: 10 });
  lines.push({ text: sanitize("Development / demo report. This workflow does not contact any external authority."), bold: false, size: 8 });
  BL();

  H("1. Incident Overview");
  KV("Incident ID", val(r.incident_id));
  KV("Scan ID", val(r.scan_id));
  KV("Timestamp", val(r.timestamp));
  KV("Platform", val(r.platform));
  KV("Input Type", val(r.input_type));
  KV("Threat Type", val(r.threat_type));
  KV("Risk Score", r.risk_score != null ? r.risk_score + "/100" : null);
  KV("Severity", val(r.severity));
  KV("Confidence", val(r.confidence));
  KV("Current Reporting Status", "Prepared (development mode - external reporting not connected)");

  let summaryTextPdf = "This incident was flagged by TruthLensAI";
  if (r.platform) summaryTextPdf += " on the " + r.platform + " platform";
  if (r.threat_type) summaryTextPdf += " as a potential " + r.threat_type + " threat";
  summaryTextPdf += ". ";
  summaryTextPdf += (r.risk_score != null) ? ("It received a risk score of " + r.risk_score + "/100") : "A risk score was not recorded";
  if (r.severity) summaryTextPdf += " with a severity rating of " + r.severity;
  if (r.confidence) summaryTextPdf += " and " + r.confidence + " confidence";
  summaryTextPdf += ".";
  H("2. Incident Summary");
  P(summaryTextPdf);

  const ocPdf = r.original_content || {};
  H("3. Original Content");
  if (r.input_type === "image" && ocPdf.extracted_text) {
    P("Extracted OCR Text:"); P(ocPdf.extracted_text);
  } else if (ocPdf.original_text) {
    P("Original Message (as received):"); P(ocPdf.original_text);
  } else if (ocPdf.extracted_text) {
    P("Extracted OCR Text:"); P(ocPdf.extracted_text);
  } else {
    P("Original content not available for this incident.");
  }

  // Audio transcript & forensics (audio incidents only; additive).
  if (r.input_type === "audio") {
    H("Audio Transcript");
    P((r.transcript != null && r.transcript !== "") ? r.transcript : "Transcript not available.");
    H("Audio Forensics");
    const afx = (r.audio_forensics && typeof r.audio_forensics === "object") ? r.audio_forensics : null;
    if (!afx) {
      P("Audio forensic data not available.");
    } else {
      const px = (afx.pitch && typeof afx.pitch === "object") ? afx.pitch : {};
      const spx = (afx.spectral && typeof afx.spectral === "object") ? afx.spectral : {};
      KV("Duration (s)", val(afx.duration_seconds));
      KV("Sample Rate (Hz)", val(afx.sample_rate));
      KV("RMS Energy", val(afx.rms_energy));
      KV("Pitch Mean (Hz)", val(px.mean_hz));
      KV("Pitch Std (Hz)", val(px.std_hz));
      KV("Spectral Centroid (Hz)", val(spx.centroid_mean_hz));
      KV("Spectral Bandwidth (Hz)", val(spx.bandwidth_mean_hz));
      const manipx = afx.possible_manipulation_indicators;
      KV("Possible manipulation indicators", manipx === true ? "Yes" : (manipx === false ? "No" : "Not available"));
    }
  }

  // Video transcript, metadata, frame & audio analysis (video incidents only; additive).
  if (r.input_type === "video") {
    const vmx = (r.video_metadata && typeof r.video_metadata === "object") ? r.video_metadata : {};
    const afv = (r.audio_forensics && typeof r.audio_forensics === "object") ? r.audio_forensics : null;
    const trv = (r.transcription && typeof r.transcription === "object") ? r.transcription : {};

    H("Video Transcript");
    P((r.transcript != null && r.transcript !== "") ? r.transcript : "Transcript not available.");

    H("Video Metadata");
    const vDur = (vmx.duration_seconds != null ? vmx.duration_seconds : (vmx.duration != null ? vmx.duration : null));
    let vRes = null;
    if (vmx.resolution != null && vmx.resolution !== "") { vRes = String(vmx.resolution); }
    else if (vmx.width != null && vmx.height != null) { vRes = String(vmx.width) + "x" + String(vmx.height); }
    const vFps = (vmx.fps != null ? vmx.fps : (vmx.frame_rate != null ? vmx.frame_rate : null));
    const vCodec = (vmx.codec != null ? vmx.codec : (vmx.video_codec != null ? vmx.video_codec : null));
    const vAudioPresent = (vmx.has_audio != null ? vmx.has_audio : (vmx.audio_present != null ? vmx.audio_present : null));
    KV("Duration (s)", val(vDur));
    KV("Resolution", val(vRes));
    KV("FPS", val(vFps));
    KV("Codec", val(vCodec));
    KV("Audio present", vAudioPresent === true ? "Yes" : (vAudioPresent === false ? "No" : "Not available"));

    H("Frame Analysis");
    let vFrameCount = null;
    if (Array.isArray(r.frames)) { vFrameCount = r.frames.length; }
    else if (r.frames && typeof r.frames === "object" && r.frames.count != null) { vFrameCount = r.frames.count; }
    else if (typeof r.frames === "number") { vFrameCount = r.frames; }
    KV("Sampled frames", val(vFrameCount));
    const vFrameManip = (vmx.possible_manipulation_indicators != null ? vmx.possible_manipulation_indicators : null);
    KV("Possible manipulation indicators", vFrameManip === true ? "Yes" : (vFrameManip === false ? "No" : "Not available"));
    let vFrameOcr = "";
    if (Array.isArray(r.frame_ocr_text)) { vFrameOcr = r.frame_ocr_text.filter(t => t != null && String(t).trim() !== "").join(" | "); }
    else if (typeof r.frame_ocr_text === "string") { vFrameOcr = r.frame_ocr_text; }
    P("OCR text found in frames: " + ((vFrameOcr && String(vFrameOcr).trim() !== "") ? vFrameOcr : "No OCR text found in frames"));

    H("Audio Analysis");
    if (!afv) {
      P("Audio forensic data not available.");
    } else {
      const pv = (afv.pitch && typeof afv.pitch === "object") ? afv.pitch : {};
      const spv = (afv.spectral && typeof afv.spectral === "object") ? afv.spectral : {};
