      P("- " + text);
    }
  } else {
    P("No specific indicators were recorded for this incident.");
  }

  const entPdf = r.extracted_entities || {};
  H("5. Extracted Entities");
  const entLine = (label, a) => { if (Array.isArray(a) && a.length) KV(label, a.join(", ")); };
  const before5 = lines.length;
  entLine("URLs", entPdf.urls);
  entLine("UPI IDs", entPdf.upi_ids);
  entLine("Phone Numbers", entPdf.phone_numbers);
  entLine("Email Addresses", entPdf.emails);
  if (lines.length === before5) P("No entities were extracted from this incident.");

  const aiPdf = r.ai_analysis || {};
  const aiBoolPdf = (v) => v === true ? "Detected" : (v === false ? "Not detected" : (v == null ? "Not available" : v));
  H("6. AI Assessment");
  KV("Scam Intent", aiBoolPdf(aiPdf.scam_intent));
  KV("Social Engineering", aiBoolPdf(aiPdf.social_engineering));
  KV("Impersonation", aiBoolPdf(aiPdf.impersonation));
  KV("Financial Manipulation", aiBoolPdf(aiPdf.financial_manipulation));
  KV("Urgency", aiPdf.urgency != null ? aiPdf.urgency : "Not available");
  KV("Confidence", aiPdf.confidence != null ? aiPdf.confidence : "Not available");
  KV("AI Threat Type", aiPdf.threat_type != null ? aiPdf.threat_type : "Not available");
