      idx++;
      if (vtListPdf.length > 1) P("Result " + idx + ":");
      const stats = (v.stats && typeof v.stats === "object") ? v.stats : v;
      const g = (k) => (stats && stats[k] != null) ? stats[k] : null;
      KV("URL", v.url != null ? v.url : (v.value != null ? v.value : null));
      KV("Status", v.status != null ? v.status : (v.vt_status != null ? v.vt_status : null));
      KV("Malicious Engines", g("malicious"));
