  const wrapChars = (size) => size >= 18 ? 46 : (size >= 13 ? 70 : 95);
  const wrapped = [];
  for (const ln of lines) {
    const maxc = wrapChars(ln.size);
    if (ln.text === "") { wrapped.push({ text: "", bold: ln.bold, size: ln.size, gapBefore: ln.gapBefore || 0 }); continue; }
    const words = String(ln.text).split(/\s+/);
    let cur = "";
    let first = true;
    for (const w of words) {
      const candidate = cur ? cur + " " + w : w;
      if (candidate.length > maxc && cur) {
        wrapped.push({ text: cur, bold: ln.bold, size: ln.size, gapBefore: first ? (ln.gapBefore || 0) : 0 });
        cur = w; first = false;
      } else {
        cur = candidate;
      }
    }
    wrapped.push({ text: cur, bold: ln.bold, size: ln.size, gapBefore: first ? (ln.gapBefore || 0) : 0 });
  }

  const pageHeight = 842, pageWidth = 595, top = 800, bottom = 50, leftX = 50;
  const pages = [];
  let curPage = [];
  let y = top;
  for (const ln of wrapped) {
    const lh = ln.size >= 18 ? 24 : (ln.size >= 13 ? 18 : 14);
    if (ln.gapBefore) y -= ln.gapBefore;
    if (y - lh < bottom) { pages.push(curPage); curPage = []; y = top; }
    curPage.push({ text: ln.text, bold: ln.bold, size: ln.size, y: y });
    y -= lh;
  }
  if (curPage.length) pages.push(curPage);
  if (!pages.length) pages.push([]);

  const escapePdf = (s) => s.replace(/\\/g, "\\\\").replace(/\(/g, "\\(").replace(/\)/g, "\\)");
  const objects = [];
  const pageObjNums = [];
  const numObjects = 2 + pages.length * 2 + 2;
  const fontRegularNum = numObjects - 1;
  const fontBoldNum = numObjects;

  objects[1] = "<< /Type /Catalog /Pages 2 0 R >>";

  let objNum = 3;
  for (let i = 0; i < pages.length; i++) {
    const pageNum = objNum++;
    const contentNum = objNum++;
    pageObjNums.push(pageNum);
    let stream = "";
    for (const item of pages[i]) {
      const f = item.bold ? "/F2" : "/F1";
      stream += "BT " + f + " " + item.size + " Tf " + leftX + " " + item.y + " Td (" + escapePdf(item.text) + ") Tj ET\n";
    }
    objects[pageNum] = "<< /Type /Page /Parent 2 0 R /MediaBox [0 0 " + pageWidth + " " + pageHeight + "] /Resources << /Font << /F1 " + fontRegularNum + " 0 R /F2 " + fontBoldNum + " 0 R >> >> /Contents " + contentNum + " 0 R >>";
    objects[contentNum] = "<< /Length " + Buffer.byteLength(stream, "latin1") + " >>\nstream\n" + stream + "endstream";
  }

  objects[2] = "<< /Type /Pages /Kids [" + pageObjNums.map(n => n + " 0 R").join(" ") + "] /Count " + pages.length + " >>";
  objects[fontRegularNum] = "<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica /Encoding /WinAnsiEncoding >>";
  objects[fontBoldNum] = "<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica-Bold /Encoding /WinAnsiEncoding >>";

  let pdf = "%PDF-1.4\n";
  const offsets = [];
  for (let n = 1; n <= numObjects; n++) {
    offsets[n] = Buffer.byteLength(pdf, "latin1");
    pdf += n + " 0 obj\n" + objects[n] + "\nendobj\n";
  }
  const xrefStart = Buffer.byteLength(pdf, "latin1");
  pdf += "xref\n0 " + (numObjects + 1) + "\n";
  pdf += "0000000000 65535 f \n";
  for (let n = 1; n <= numObjects; n++) {
    pdf += String(offsets[n]).padStart(10, "0") + " 00000 n \n";
  }
  pdf += "trailer\n<< /Size " + (numObjects + 1) + " /Root 1 0 R >>\nstartxref\n" + xrefStart + "\n%%EOF";

  return Buffer.from(pdf, "latin1");
};

const pdfBuffer = buildIncidentPdf(r);

return [{
  json: { subject: subject, incident_id: incident_id, threat_type: threat_type, email_html: html },
  binary: {
    report: {
      data: pdfBuffer.toString("base64"),
      fileName: fileName,
      mimeType: "application/pdf"
    }
  }
}];

