  };

  // Original text only when actually available.
  if (originalText !== undefined && originalText !== null && originalText !== "") {
    evidencePack.original_text = originalText;
  }

  // Audio scans: preserve transcript, transcription metadata, and forensics.
  if (isAudio) {
    evidencePack.input_type = "audio";
    if (d.transcript !== undefined && d.transcript !== null) {
      evidencePack.transcript = d.transcript;
    }
    if (d.transcription !== undefined && d.transcription !== null) {
      evidencePack.transcription = d.transcription;
    }
    if (d.audio_forensics !== undefined && d.audio_forensics !== null) {
      evidencePack.audio_forensics = d.audio_forensics;
    }
  } else if (isVideo) {
    // Video scans: preserve transcript, transcription, video metadata,
    // frame data, frame OCR text, and audio forensics.
    evidencePack.input_type = "video";
    if (d.transcript !== undefined && d.transcript !== null) {
      evidencePack.transcript = d.transcript;
    }
    if (d.transcription !== undefined && d.transcription !== null) {
      evidencePack.transcription = d.transcription;
    }
    if (d.video_metadata !== undefined && d.video_metadata !== null) {
      evidencePack.video_metadata = d.video_metadata;
    }
    if (d.frames !== undefined && d.frames !== null) {
      evidencePack.frames = d.frames;
    }
    if (d.frame_ocr_text !== undefined && d.frame_ocr_text !== null) {
      evidencePack.frame_ocr_text = d.frame_ocr_text;
    }
    if (d.audio_forensics !== undefined && d.audio_forensics !== null) {
      evidencePack.audio_forensics = d.audio_forensics;
    }
  } else if (isImage) {
    // Image scans: preserve extracted_text and mark input_type.
    evidencePack.input_type = "image";
    if (typeof d.extracted_text === "string") {
      evidencePack.extracted_text = d.extracted_text;
    }
  } else {
    evidencePack.input_type = "text";
  }

  out.push({ json: { incident_evidence: evidencePack } });
}

return out;

